P = [
 dict(pmid='43044756', doi='10.1016/j.envpol.2026.129524', journal='Environ Pollut', title='Year-round organic aerosol sources in the Po Valley: A comparative study of Bologna and Milan within RI-URBANS', short='Po Valley Bologna Milan 2023 ACSM NR-PM1 variable-factor-number PMF BBOA SOA 75%', design='Source apportionment', pm='Non-refractory PM1 composition by Aerosol Chemical Speciation Monitor at two urban background sites, 2023', geo='Italy (Bologna, Milan)', endpoint='Organic aerosol factors (HOA, BBOA, LO-OOA, MO-OOA) by season and site', tier='B', basis='Lab / research instrument', affil='Institute of Atmospheric Sciences and Climate, CNR, Italy; Institute of Atmospheric Sciences and Climate, CNR, Italy', n='Simultaneous year-long (2023) ACSM measurements of NR-PM1 at Bologna and Milan urban background sites, with a new variable-factor-number PMF that constrains biomass-burning OA only when f60 exceeds 0.3%, avoiding warm-season BBOA overestimation. Mean NR-PM1 was 8.02 +/- 8.63 ug/m3 (Bologna) and 8.37 +/- 8.10 (Milan); OA dominated year-round. Primary OA (HOA plus BBOA) was 8-23% of OA; secondary OA exceeded 75%, MO-OOA alone 45-50%. Winter peaks followed stagnation, summer SOA photochemistry. Two sites cannot by themselves establish basin-wide homogeneity, and the f60 threshold is a tuning choice. Relevance: moderate - a regionally homogeneous, SOA-dominated PM1 means low-cost networks in the basin mostly resolve meteorology, not local sources.', sub=corpus.EXPO),
 dict(pmid='', doi='10.3390/atmos17111132', journal='Atmosphere', title='Ambient PM10 Patterns in Provinces Affected by the 2023 Turkiye Earthquakes: A Descriptive Assessment of 2022-2023 Monitoring Data', short='Turkiye 2023 earthquakes 11 provinces 28 stations PM10 2022 vs 2023 AirQ+ attributable proportion', design='Network monitoring + burden', pm='Daily PM10 from 28 national regulatory monitoring stations, 2022-2023', geo='Turkiye', endpoint='Annual PM10, exceedance days, AirQ+ attributable proportion of all-cause mortality', tier='C', basis='Reference / regulatory monitor', affil='Istanbul Provincial Health Directorate, Turkiye; Istanbul University-Cerrahpasa, Turkiye', n='Descriptive comparison of daily PM10 from 28 stations in 11 provinces hit by the February 2023 earthquakes, 2023 against 2022. Annual means rose in four provinces and fell in seven; Kahramanmaras rose most (33.0%), Elazig fell most (13.4%). Exceedance days rose from 144 to 218 in Kahramanmaras and 109 to 143 in Hatay. All provinces exceeded the WHO 15 ug/m3 guideline both years; AirQ+ attributable proportion of mortality reached 17.36% against a 40 ug/m3 counterfactual. The authors concede no unaffected comparison provinces and no meteorological adjustment, so nothing is attributable to the earthquake, and stations damaged in the disaster may bias coverage. Relevance: direct - post-disaster demolition dust is where rapidly deployable sensors outperform a damaged fixed network.', sub=corpus.BURD),
 dict(pmid='', doi='10.3390/atmos17111135', journal='Atmosphere', title='Distinct Source Signatures of Two Asian Dust Events Revealed by Pb Isotopes in PM10', short='Korea coastal industrial site 2023 Asian dust PM10 Pb isotopes Bayesian mixing Kumtag Gobi', design='Source apportionment', pm='PM10 filter samples March-April 2023, ions, elements and Pb isotope ratios', geo='South Korea', endpoint='Source contributions to PM10 during Asian dust and non-dust periods', tier='C', basis='Lab / research instrument', affil='National Institute of Environmental Research, South Korea; National Institute of Environmental Research, South Korea', n='PM10 sampled March-April 2023 at a coastal industrial site in Korea, analysed for ions, elements and Pb isotopes, with Bayesian source apportionment and back trajectories. PM10 averaged 130.5 ug/m3 during Asian dust versus 77.4 during non-dust; 208Pb/206Pb 2.1187 versus 2.0999. The March and April dust events had similar PM10 and chemistry but different isotopes (p<0.01): March weighted to the Kumtag Desert and coal, April to the Gobi and industry. Two events at one site, and Bayesian mixing results depend on end-member libraries not described in the abstract. Relevance: low - isotopic source discrimination is invisible to mass-only sensors, though dust events are a known LCS undercount regime.', sub=corpus.EXPO),
 dict(pmid='43041689', doi='10.1016/j.ese.2026.100787', journal='Environ Sci Ecotechnol', title='Landfill mining resuspends buried micro- and nanoplastics as airborne particles.', short='Tongji active landfill mining TSP Andersen impactor airborne micro-nanoplastics hopper PET Gaussian plume inhalation dose', design='Field campaign', pm='TSP (100 um inlet) and Andersen cascade impactor 0.43-10 um fractions, polymer-resolved micro- and nanoplastics', geo='China', endpoint='Airborne MNP concentration by process, downwind dispersion, estimated inhalation dose', tier='C', basis='Lab / research instrument', affil='Tongji University, China; Tongji University, China', n='Field sampling at an active landfill mining site with TSP and size-segregated Andersen impactor samples (0.43-10 um). The hopper process generated the highest airborne micro- and nanoplastic (MNP) concentrations; PET was the most abundant polymer by mass; MNPs made up 0.04-9.9% of 0.43-10 um aerosol mass and co-varied with TSP. A density-corrected Gaussian plume placed maximum concentrations 2.7 m (TSP microplastics) and 4.4 m (aerosol MNPs) downwind, and inhalation exposure was estimated at 16-19,271 ng/kg/day. A single site, no stated sampling duration, and a three-order-of-magnitude dose range show how assumption-driven the exposure estimate is. Relevance: moderate - co-emission with TSP suggests a cheap PM proxy for MNP release at waste sites.', sub=corpus.OCC),
]
